import test from 'node:test';import assert from 'node:assert/strict';import {mkdtemp,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import path from 'node:path';import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),{createBackend}=require('../electron/backend.cjs');
async function setup(t){const dir=await mkdtemp(path.join(tmpdir(),'quality-center-'));t.after(()=>rm(dir,{recursive:true,force:true}));const b=createBackend({dataDir:dir,modelMode:'managed'});t.after(()=>b.dispose());await b.execute({action:'add-store',values:{platform:'pdd-web',storeName:'甲店'}});return {b,dir,id:b.snapshot().stores[0].id};}
test('uncertain delivery queues a conversation review without stopping another conversation or globally disabling AI',async t=>{const {b,id}=await setup(t);let stopped=0,taken=[];b.engine.stopAll=()=>{stopped++};b.engine.worker=()=>({takeOver:uid=>taken.push(uid)});b.ingest({type:'message:in',storeId:id,uid:'a',from:'buyer',content:'问题甲'});b.engine.aiClient.onDeliveryFailure({reason:'send_unconfirmed',storeId:id,uid:'a',reply:'回答甲'});assert.equal(stopped,0);assert.equal(b.snapshot().modelIssue,null);const row=b.snapshot().quality.find(r=>r.uid==='a');assert.equal(row.events[0].code,'delivery_unconfirmed');assert.equal(row.status,'pending');assert.deepEqual(taken,['a']);});
test('review requires a matching version, persists notes and never sends or resumes AI',async t=>{const {b,id,dir}=await setup(t);b.ingest({type:'message:in',storeId:id,uid:'a',from:'buyer',content:'问题'});let row=b.snapshot().quality[0];await b.execute({action:'review-conversation',values:{id:row.id,version:row.version,status:'passed',note:'检查通过'}});assert.equal(b.snapshot().quality[0].status,'passed');b.ingest({type:'message:in',storeId:id,uid:'a',from:'buyer',content:'新问题',ts:Date.now()+100});await assert.rejects(b.execute({action:'review-conversation',values:{id:row.id,version:row.version,status:'passed',note:'旧结果'}}),/更新/);b.dispose();const restored=createBackend({dataDir:dir,modelMode:'managed'});t.after(()=>restored.dispose());assert.equal(restored.snapshot().quality[0].note,'检查通过');assert.equal(restored.snapshot().quality[0].status,'pending');});
test('legacy review migration preserves the original file and is idempotent',async t=>{const {writeFile,readFile}=await import('node:fs/promises');const {b,id,dir}=await setup(t);b.ingest({type:'message:in',storeId:id,uid:'legacy',from:'buyer',content:'旧问题'});b.dispose();const file=path.join(dir,'managed-model-issue.json'),raw=JSON.stringify({code:'delivery_unconfirmed',at:Date.now()+1000,context:{storeId:id,uid:'legacy',buyerMessage:'旧问题',reply:'旧回复'}});await writeFile(file,raw);for(let i=0;i<2;i++){const next=createBackend({dataDir:dir,modelMode:'managed'});try{assert.equal(next.snapshot().modelIssue,null);assert.equal(next.snapshot().quality.find(r=>r.uid==='legacy').events.length,1);assert.equal(next.snapshot().conversations[0].status,'handoff');}finally{next.dispose()}}assert.equal(await readFile(file,'utf8'),raw);});
test('disk failure during delivery review still suppresses the conversation before persistence',async t=>{const {mkdir}=await import('node:fs/promises');const {b,id,dir}=await setup(t);let suppressed=false;b.engine.worker=()=>({takeOver(){suppressed=true}});await mkdir(path.join(dir,'conversation-quality.json'));b.engine.aiClient.onDeliveryFailure({reason:'send_unconfirmed',storeId:id,uid:'a',reply:'answer'});assert.equal(suppressed,true);assert.equal(b.snapshot().modelIssue.code,'storage_unavailable');});
test('a fresh buyer message releases only the old quality hold, without approving or resending it',async t=>{const {b,id}=await setup(t);let reason='',cleared=0;b.engine.worker=()=>({takeOver(_uid,source){reason=source},clearManualSuppression(_uid,source){if(source!==reason)return false;cleared++;reason='';return true}});const at=Date.now();b.ingest({type:'message:in',storeId:id,uid:'a',from:'buyer',content:'旧问题',ts:at-100});b.engine.aiClient.onDeliveryFailure({reason:'send_unconfirmed',storeId:id,uid:'a',reply:'旧回答'});assert.equal(b.snapshot().quality[0].events[0].resolved,false);b.ingest({type:'message:in',storeId:id,uid:'a',from:'buyer',content:'新问题',ts:at+2000});assert.equal(cleared,1);assert.equal(b.snapshot().quality[0].events[0].resolved,true);assert.equal(b.snapshot().quality[0].status,'pending');assert.equal(b.snapshot().conversations[0].status,'pending');});
test('releasing an older event keeps a newer unresolved event in handoff',async t=>{const {writeFile}=await import('node:fs/promises');const {b,id,dir}=await setup(t);const now=Date.now();b.ingest({type:'message:in',storeId:id,uid:'a',from:'buyer',content:'旧问题',ts:now-1000});b.engine.aiClient.onDeliveryFailure({reason:'send_unconfirmed',storeId:id,uid:'a',reply:'answer'});const rows=b.snapshot().quality;rows[0].events.push({...rows[0].events[0],key:'later',at:now+5000});b.dispose();await writeFile(path.join(dir,'conversation-quality.json'),JSON.stringify({version:1,rows}));const next=createBackend({dataDir:dir,modelMode:'managed'});t.after(()=>next.dispose());let clears=0;next.engine.worker=()=>({clearManualSuppression(){clears++;return true}});next.ingest({type:'message:in',storeId:id,uid:'a',from:'buyer',content:'中间时间消息',ts:now+2000});assert.equal(clears,0);assert.equal(next.snapshot().conversations[0].status,'handoff');assert.equal(next.snapshot().quality[0].events[1].resolved,false);});

